write(
    "tests/Partcounter.Tests/ActiveOrderRecoveryTests.cs",
    '''using Partcounter.Models;\nusing Partcounter.Services;\nusing Xunit;\n\nnamespace Partcounter.Tests;\n\npublic sealed class ActiveOrderRecoveryTests\n{\n    [Fact]\n    public async Task RecoveryStore_RoundTripsCheckpoint()\n    {\n        var root = Path.Combine(Path.GetTempPath(), "PartcounterRecoveryTests", Guid.NewGuid().ToString("N"));\n        Directory.CreateDirectory(root);\n        var db = Path.Combine(root, "recovery.db");\n        var service = new ActiveOrderRecoveryService(db);\n        await service.InitializeAsync();\n\n        var checkpoint = CreateCheckpoint();\n        await service.UpsertAsync(checkpoint);\n        var loaded = Assert.Single(await service.LoadAsync());\n        Assert.Equal(checkpoint.MachineNumber, loaded.MachineNumber);\n        Assert.Equal(checkpoint.OrderNumber, loaded.OrderNumber);\n        Assert.Equal(checkpoint.JobId, loaded.JobId);\n        Assert.Equal(checkpoint.ScheduledHoldAfterVeNumber, loaded.ScheduledHoldAfterVeNumber);\n        Assert.Equal(checkpoint.ManualVeReconfigurationPending, loaded.ManualVeReconfigurationPending);\n        Assert.Equal(checkpoint.Phase, loaded.Phase);\n\n        await service.DeleteAsync(checkpoint.MachineNumber);\n        Assert.Empty(await service.LoadAsync());\n    }\n\n    [Fact]\n    public void MachineState_RestoresLiveSnapshotPausedWithoutDuplicateCompletion()\n    {\n        var machine = new MachineState\n        {\n            Configuration = new MachineConfiguration(1, "M01", "127.0.0.1")\n        };\n        var checkpoint = CreateCheckpoint();\n        var snapshot = new LogoSnapshot(\n            CurrentParts: 256,\n            TotalCycles: 20,\n            CurrentVeNumber: 2,\n            CompletedVes: 1,\n            LastCompletedVeQuantity: 1024,\n            StatusWord: (ushort)(ModbusRegisterMap.StatusReady | ModbusRegisterMap.StatusCompletionHoldArmed),\n            AcknowledgedCommandSequence: 7,\n            ActiveCavitiesEcho: 64,\n            LastCompletedVeNumber: 1,\n            CompletionSequence: 5,\n            LogoHeartbeat: 10,\n            ErrorCode: 0,\n            LastCompletionReason: VeCompletionReason.AutomaticFull,\n            ReadAtUtc: DateTime.UtcNow,\n            HoldAfterVeNumberEcho: 2,\n            JobIdEcho: checkpoint.JobId);\n\n        var completions = 0;\n        machine.VeCompleted += (_, _) => completions++;\n        machine.RestoreRecoveredOrder(checkpoint, snapshot);\n\n        Assert.Equal(ProductionOrderState.Paused, machine.OrderState);\n        Assert.Equal((uint)1280, machine.OrderProducedQuantity);\n        Assert.Equal((uint)1000, machine.CurrentVeTargetParts);\n        Assert.Equal((ushort)2, machine.CurrentVeNumber);\n\n        machine.ApplyLogoSnapshot(snapshot);\n        Assert.Equal(0, completions);\n    }\n\n    [Fact]\n    public void PendingFinalVe_RestoresCorrectOriginalVeTarget()\n    {\n        var machine = new MachineState\n        {\n            Configuration = new MachineConfiguration(1, "M01", "127.0.0.1")\n        };\n        var checkpoint = CreateCheckpoint() with\n        {\n            OrderTargetQuantity = 2500,\n            StandardVeTarget = 1000,\n            ScheduledHoldAfterVeNumber = 3\n        };\n        var snapshot = new LogoSnapshot(\n            CurrentParts: 128,\n            TotalCycles: 34,\n            CurrentVeNumber: 3,\n            CompletedVes: 2,\n            LastCompletedVeQuantity: 1024,\n            StatusWord: ModbusRegisterMap.StatusCompletionHoldArmed,\n            AcknowledgedCommandSequence: 8,\n            ActiveCavitiesEcho: 64,\n            LastCompletedVeNumber: 2,\n            CompletionSequence: 6,\n            LogoHeartbeat: 11,\n            ErrorCode: 0,\n            LastCompletionReason: VeCompletionReason.AutomaticFull,\n            ReadAtUtc: DateTime.UtcNow,\n            HoldAfterVeNumberEcho: 3,\n            JobIdEcho: checkpoint.JobId);\n\n        machine.RestoreRecoveredOrder(checkpoint, snapshot);\n        Assert.Equal((uint)452, machine.CurrentVeTargetParts);\n    }\n\n    private static ActiveOrderCheckpoint CreateCheckpoint() => new(\n        MachineNumber: 1,\n        OrderNumber: "AUF-RECOVERY-001",\n        JobId: 123456u,\n        ArticleNumber: "A-01",\n        ArticleDescription: "Recovery Test",\n        ToolNumber: "WZ-01",\n        ActiveCavities: 64,\n        StandardVeTarget: 1000,\n        OrderTargetQuantity: 10000,\n        OrderState: ProductionOrderState.Running,\n        ScheduledHoldAfterVeNumber: 2,\n        ManualVeReconfigurationPending: false,\n        IsTemporarilyDisabled: false,\n        LastKnownOrderProducedQuantity: 1024,\n        LastKnownCurrentParts: 0,\n        LastKnownTotalCycles: 16,\n        LastKnownCurrentVeNumber: 2,\n        LastKnownCompletedVes: 1,\n        LastKnownLastCompletedVeQuantity: 1024,\n        Phase: ActiveOrderCheckpointPhase.Active,\n        UpdatedAtUtc: DateTime.UtcNow);\n}\n''',
)

write(
    "docs/RESTART_RECOVERY_R001_25.md",
    '''# Partcounter R001.25 – 24/7 Neustart-Recovery\n\n## Ziel\nEin PC-/Partcounter-Neustart darf einen real in der Siemens LOGO! laufenden Auftrag nicht als neuen oder unbekannten Auftrag behandeln. Der PC-Zustand wird deshalb zusätzlich als SQLite-Recovery-Checkpoint persistiert.\n\n## Persistierter Zustand\nPro Maschine wird maximal ein offener Echtauftrag gespeichert, u. a. mit Auftragsnummer, stabiler JobId, Artikel/Werkzeug, Kavitäten, Standard-VE, Auftragsmenge, geplanter Hold-Grenze, manueller-VE-Pending-Status sowie den zuletzt bekannten Zählerständen. Simulation wird nicht als Echtauftrag persistiert.\n\n## Crashfenster beim Auftragsstart\nVor dem Modbus-Auftragswrite wird `PendingActivation` persistiert.\n- Wird die LOGO!-Übernahme bestätigt, wird daraus `Active`.\n- Scheitert die Übertragung kontrolliert, wird der Checkpoint gelöscht.\n- Nach einem Crash wird ein Pending-Checkpoint nur übernommen, wenn `JobIdEcho` der realen LOGO! exakt passt. Passt er nicht, wird der Pending-Checkpoint verworfen, ohne einen fremden LOGO!-Auftrag zu verändern.\n\n## Programmstart\nRecovery-Aufträge werden lokal ausschließlich als **PAUSIERT** geladen. Im Simulationsmodus sind Resume, Reset, manueller VE-Wechsel und andere zustandsverändernde Aktionen für diese Aufträge gesperrt. Dadurch kann die Simulationsuhr niemals einen echten Recovery-Auftrag fortzählen.\n\n## Umschalten in Echtbetrieb\nFür jede Recovery-Maschine:\n1. frischen Protocol-V3-Snapshot lesen,\n2. `JobIdEcho` und `ActiveCavitiesEcho` prüfen,\n3. bei passender Identität `PauseCounting` senden und Ack abwarten,\n4. neuen Snapshot lesen,\n5. HoldAfterVE gegen Checkpoint bzw. deterministische aktuelle Planung prüfen,\n6. MachineState aus dem echten LOGO-Zählerstand rekonstruieren,\n7. Auftrag absichtlich pausiert lassen.\n\nErst danach kann der Bediener `Fortsetzen` wählen; die bestehende Boundary-Recovery aktualisiert bei bereits erreichtem Hold zuerst Ziel/Hold und gibt erst anschließend die Zählung frei.\n\n## Offline produzierte VEs\nWenn die LOGO! während des PC-Ausfalls weitere Voll-VE produziert hat, wird der echte Zählerstand übernommen. Partcounter erzeugt **keine erfundenen Abschlusszeitpunkte**. Stattdessen wird `RECOVERY_OFFLINE_PROGRESS` protokolliert; fehlende historische Zeitstempel bleiben transparent als Recovery-Lücke erkennbar.\n\n## Manueller VE-Wechsel während Neustart\nWar ein manueller VE-Wechsel pending und die LOGO! zeigt über `CompletedVEs` plus `LastCompletionReason=Manual` eindeutig dessen Abschluss, wird die nächste VE unter bestätigter Pause neu geplant. Ist der Abschluss nicht eindeutig, bleibt normales Resume gesperrt.\n\n## Freigabegrenze\nCI prüft Persistenz, Rekonstruktion und Doppel-Completion-Schutz. Die reale Wiederanlaufwirkung wird zusätzlich an M01 mit echtem Partcounter-Abbruch/Neustart und LOGO!-Weiterlauf abgenommen.\n''',
)

print("R001.25 restart recovery hardening patch applied")
